  FOREACH table_name IN ARRAY ARRAY['schema_migrations','accounts','profiles','favorites','credentials','operations','quota','erasures','public_releases','revocations','content_sources','catalog_releases','catalog_release_sources','catalog_foods','catalog_food_aliases','catalog_food_relations','catalog_nutrition','catalog_recipes','catalog_variants','catalog_variant_lines','catalog_variant_steps','catalog_search_documents','app_sessions','user_consents']::text[] LOOP
